window.IAM_DATA = {"questions":[{"ref":"G1.01","tier":"gate","group":"gate","section":"Account & Edition","question":"Which Docusign IAM edition is the account licensed for?","why":"Edition determines which modules are available at all. Obligation Management, CLM interoperability and custom extraction limits are all edition-gated.","atype":"Single select","options":["IAM Essentials","IAM Standard","IAM Pro","IAM Enterprise","IAM for Sales","Not yet purchased"],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"If 'Not yet purchased' -> flag as pre-sales, complete Tier 2 only","considerations":"Custom extraction limits differ by edition (Pro/Enterprise/Sales: 50 combined, 15 custom types max)."},{"ref":"G1.02","tier":"gate","group":"gate","section":"Account & Edition","question":"Is Agreement Manager already provisioned and live on the account?","why":"Determines whether this is a net-new implementation or an optimisation of an existing deployment.","atype":"Yes / No","options":["Yes","No"],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"If No -> ask G1.03. If Yes -> skip to G1.04","considerations":""},{"ref":"G1.03","tier":"gate","group":"gate","section":"Account & Edition","question":"What is the target provisioning date, and who owns the Docusign relationship?","why":"Historical ingestion begins at provisioning and can take over a week, so this anchors the whole plan.","atype":"Free text","options":[],"guidance":"","triggerText":"G1.02 = No","showIf":{"all":[{"ref":"G1.02","op":"eq","value":"No"}]},"routing":"","considerations":"Historical ingestion runs automatically at provisioning and is all-or-nothing."},{"ref":"G1.04","tier":"gate","group":"gate","section":"Account & Edition","question":"Is this a single Docusign account, or multiple accounts under one organisation?","why":"Agreement Manager permissions and audit logs are managed per account, not at organisation level.","atype":"Single select","options":["Single account","Multiple accounts","Unsure"],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"If 'Multiple accounts' -> ask G1.05","considerations":"Audit events are captured at account level. Agreement Manager is issued at account level, not org level."},{"ref":"G1.05","tier":"gate","group":"gate","section":"Account & Entity","question":"Which accounts are in scope, and do agreements need to be visible across account boundaries?","why":"There is no cross-account agreement visibility; this often forces a consolidation decision.","atype":"Free text","options":[],"guidance":"","triggerText":"G1.04 = Multiple accounts","showIf":{"all":[{"ref":"G1.04","op":"eq","value":"Multiple accounts"}]},"routing":"","considerations":"No cross-account repository. Consolidation or separate deployments may be required."},{"ref":"G1.06","tier":"gate","group":"gate","section":"Region & Compliance","question":"Which datacenter region is the account provisioned in?","why":"Region drives language support behaviour and the 'English (Global)' vs 'English (U.S.)' distinction.","atype":"Single select","options":["US","EU","Canada","Australia","Japan","Unsure"],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"","considerations":"Data may be processed outside the provisioned region. Obligations AI runs on a U.S. server."},{"ref":"G1.07","tier":"gate","group":"gate","section":"Region & Compliance","question":"Is the account FedRAMP or GovRAMP?","why":"Email ingestion is not supported on FedRAMP/GovRAMP accounts, which removes an entire intake route.","atype":"Yes / No","options":["Yes","No","Unsure"],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"If Yes -> skip M1.07-M1.09 (email ingestion)","considerations":"Email attachment ingestion is NOT supported on FedRAMP/GovRAMP accounts."},{"ref":"G1.08","tier":"gate","group":"gate","section":"Region & Compliance","question":"Are there data residency or sovereignty requirements that restrict where agreement data may be processed?","why":"AI processing may occur outside the provisioned region; this must be disclosed early.","atype":"Free text","options":[],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"","considerations":"Documented limitation: data may be processed outside the provisioned region."},{"ref":"G1.09","tier":"gate","group":"gate","section":"Volume & Scale","question":"Approximately how many completed agreements exist in Docusign eSignature today?","why":"Tests the account against the historical ingestion ceiling.","atype":"Number","options":[],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"If > 100,000 -> ask G1.10","considerations":"Ingestion ceiling: 500,000 (North America) / 100,000 (International)."},{"ref":"G1.10","tier":"gate","group":"gate","section":"Volume & Scale","question":"Is the account provisioned as North American or International?","why":"Sets which ingestion ceiling applies (500K vs 100K).","atype":"Single select","options":["North America","International","Unsure"],"guidance":"","triggerText":"G1.09 > 100000","showIf":{"all":[{"ref":"G1.09","op":"gt","value":100000}]},"routing":"","considerations":"If volume exceeds the ceiling, ingestion is all-or-nothing; selective historical ingestion is not generally available."},{"ref":"G1.11","tier":"gate","group":"gate","section":"Volume & Scale","question":"What is the expected annual growth in completed agreements?","why":"Determines headroom against ceilings and sizing of the ongoing data review effort.","atype":"Number","options":[],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"","considerations":""},{"ref":"G1.12","tier":"gate","group":"gate","section":"Language","question":"Which languages do the in-scope agreements appear in?","why":"AI insight coverage varies significantly by language; several attribute families are English-only.","atype":"Multi select","options":["English (US)","English (other)","French","German","Spanish","Brazilian Portuguese","Japanese","Other"],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"If anything other than English (US) selected -> ask G1.13","considerations":"AI supports 6 languages. Payment Obligations are English (U.S.) only. Assignment/Liability/Jurisdiction are English+German+French only."},{"ref":"G1.13","tier":"gate","group":"gate","section":"Language","question":"Roughly what proportion of the estate is in each non-English language?","why":"Quantifies how much of the repository will have reduced AI coverage and need manual entry.","atype":"Free text","options":[],"guidance":"","triggerText":"G1.12 includes any non-English","showIf":{"any":[{"ref":"G1.12","op":"containsAny","value":["English (other)","French","German","Spanish","Brazilian Portuguese","Japanese","Other"]}]},"routing":"","considerations":"Custom types/fields are auto-supported in English (Global) only. Reports built on unsupported attributes will not populate."},{"ref":"G1.14","tier":"gate","group":"gate","section":"Existing Estate","question":"Is Docusign CLM in use, or planned?","why":"CLM changes deduplication behaviour, adds the CLM Attributes pane, and has its own interoperability roadmap.","atype":"Single select","options":["In use today","Planned","No","Unsure"],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"If 'In use today' or 'Planned' -> ask M11.01-M11.04","considerations":"CLM has its own deduplication. CLM interoperability documents are excluded from duplicate detection."},{"ref":"G1.15","tier":"gate","group":"gate","section":"Existing Estate","question":"Are there agreements stored outside Docusign that need to be brought in?","why":"Triggers the entire migration and bulk metadata workstream.","atype":"Yes / No","options":["Yes","No","Unsure"],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"If Yes -> complete Module 12 (Migration)","considerations":"Bulk upload requires an admin-granted permission. 190 MB per file, 255-character filenames."},{"ref":"G1.16","tier":"gate","group":"gate","section":"Users","question":"Approximately how many users need access, and what is the split across administrators, contract managers, and view-only users?","why":"Drives the permissions model and licence requirements.","atype":"Free text","options":[],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"","considerations":"Free participants can only see their own agreements and cannot use repository-wide features."},{"ref":"G1.17","tier":"gate","group":"gate","section":"Users","question":"Are any intended users on free/participant licences rather than full licences?","why":"Free participants cannot use most Agreement Manager features, and dashboards will load empty for them.","atype":"Yes / No","options":["Yes","No","Unsure"],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"If Yes -> flag licence gap in Considerations","considerations":"Free participants need a full licence plus permission for most features; access to others' agreements only via shared sets."},{"ref":"G1.18","tier":"gate","group":"gate","section":"Timeline","question":"What is the target go-live date, and is a phased rollout expected?","why":"Ingestion and processing timelines can run to weeks; this validates feasibility early.","atype":"Free text","options":[],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"","considerations":"Large data sets can take over a week to process. eSignature-ingested docs queue longer at month/year end (4-5 days)."},{"ref":"B2.01","tier":"business","group":"business","section":"Drivers","question":"What is the primary business driver for deploying Agreement Manager?","why":"Anchors scope. A renewals-driven deployment looks very different from a compliance-driven one.","atype":"Multi select","options":["Visibility / findability","Renewal capture","Risk & compliance","Cost reduction","Audit readiness","M&A due diligence","Other"],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"Use the answer to prioritise which domain modules are in scope","considerations":""},{"ref":"B2.02","tier":"business","group":"business","section":"Drivers","question":"What specifically goes wrong today because agreement data is hard to access?","why":"Surfaces the concrete pain that success will be measured against.","atype":"Free text","options":[],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"","considerations":""},{"ref":"B2.03","tier":"business","group":"business","section":"Drivers","question":"Has the organisation missed renewals, auto-renewed unintentionally, or missed notice periods in the last 24 months?","why":"Renewal pain is the most common and most quantifiable driver.","atype":"Yes / No","options":["Yes","No","Unsure"],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"If Yes -> prioritise Module 8 (Renewals) and quantify the loss","considerations":"Auto-extension requires accurate Expiration Date, Renewal Type and Renewal Term."},{"ref":"B2.04","tier":"business","group":"business","section":"Stakeholders","question":"Who is the executive sponsor, and who is the day-to-day process owner?","why":"Data review is an ongoing operational commitment and needs a named owner.","atype":"Free text","options":[],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"","considerations":""},{"ref":"B2.05","tier":"business","group":"business","section":"Stakeholders","question":"Which departments will use the repository, and what does each need from it?","why":"Departmental needs map directly to agreement sets, dashboards and permission design.","atype":"Free text","options":[],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"","considerations":""},{"ref":"B2.06","tier":"business","group":"business","section":"Stakeholders","question":"Who currently acts as gatekeeper for agreement requests, and what is their volume?","why":"Identifies the bottleneck the deployment is meant to relieve, and a likely champion.","atype":"Free text","options":[],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"","considerations":""},{"ref":"B2.07","tier":"business","group":"business","section":"Use Cases","question":"What are the top three questions the business needs to answer from agreement data?","why":"These become the acceptance tests for reporting and field configuration.","atype":"Free text","options":[],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"Map each answer to required fields in Module 3","considerations":""},{"ref":"B2.08","tier":"business","group":"business","section":"Compliance","question":"Are there regulatory or audit drivers (SOX, GDPR, industry-specific) shaping requirements?","why":"Drives activity log, retention and access control requirements.","atype":"Free text","options":[],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"If Yes -> ask M2.09-M2.11 (audit and access logging)","considerations":"Activity logs display 200 events max; CSV download capped at 5,000 rows; timestamps in UTC."},{"ref":"B2.09","tier":"business","group":"business","section":"Current State","question":"What tools are used today to track agreements (spreadsheets, shared drives, another CLM)?","why":"Identifies migration sources and what is being decommissioned.","atype":"Free text","options":[],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"If a system is named -> complete Module 12 (Migration)","considerations":""},{"ref":"B2.10","tier":"business","group":"business","section":"Current State","question":"Is there an existing agreement taxonomy, naming convention, or metadata standard?","why":"Determines how much of the type/field model already exists versus needs designing.","atype":"Yes / No","options":["Yes","No","Partially"],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"If Yes or Partially -> request the documentation before Module 3","considerations":""},{"ref":"B2.11","tier":"business","group":"business","section":"Success","question":"What does success look like at 3, 6 and 12 months, and how will it be measured?","why":"Without measurable targets the deployment cannot be signed off.","atype":"Free text","options":[],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"","considerations":""},{"ref":"B2.12","tier":"business","group":"business","section":"Success","question":"Who will validate AI-surfaced data, and how much time can they commit each week?","why":"Data review is the single most underestimated effort in these deployments.","atype":"Free text","options":[],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"","considerations":"Agreements remain in the review queue until every suggested value is accepted or corrected."},{"ref":"M1.01","tier":"modules","group":"M1","section":"M1 Ingestion","question":"Does this module apply? Confirm agreements will be ingested or uploaded into Agreement Manager.","why":"Module gate.","atype":"Yes / No","options":["Yes","No"],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"If No -> skip to Module 2","considerations":""},{"ref":"M1.02","tier":"modules","group":"M1","section":"M1 Ingestion","question":"Should all completed eSignature envelopes flow into Agreement Manager automatically?","why":"Automatic ingestion is the default and cannot be selectively filtered without a request.","atype":"Yes / No","options":["Yes","No","Unsure"],"guidance":"","triggerText":"M1.01 = Yes","showIf":{"all":[{"ref":"M1.01","op":"eq","value":"Yes"}]},"routing":"If No -> ask M1.03","considerations":"Ingestion filtering is not generally available; request via the account team. Ingestion is all-or-nothing."},{"ref":"M1.03","tier":"modules","group":"M1","section":"M1 Ingestion","question":"Which envelopes should be excluded, and on what basis?","why":"Establishes whether a filtering request to Docusign is needed before go-live.","atype":"Free text","options":[],"guidance":"","triggerText":"M1.02 = No","showIf":{"all":[{"ref":"M1.02","op":"eq","value":"No"}]},"routing":"Raise a filtering request with the Docusign account team","considerations":"Selective historical ingestion is not supported as standard."},{"ref":"M1.04","tier":"modules","group":"M1","section":"M1 Ingestion","question":"Do both sent and received envelopes need to be captured?","why":"Both sync by default; confirms expectations rather than changes behaviour.","atype":"Yes / No","options":["Yes","No"],"guidance":"","triggerText":"M1.01 = Yes","showIf":{"all":[{"ref":"M1.01","op":"eq","value":"Yes"}]},"routing":"","considerations":"Both sent and received envelopes sync by default."},{"ref":"M1.05","tier":"modules","group":"M1","section":"M1 Ingestion","question":"Will users upload documents directly from their devices?","why":"Single upload (up to 5 files) needs no special permission; more does.","atype":"Yes / No","options":["Yes","No"],"guidance":"","triggerText":"M1.01 = Yes","showIf":{"all":[{"ref":"M1.01","op":"eq","value":"Yes"}]},"routing":"If Yes -> ask M1.06","considerations":"Single upload capped at 5 files. Files under 190 MB, filenames under 255 characters."},{"ref":"M1.06","tier":"modules","group":"M1","section":"M1 Ingestion","question":"Will any users need to upload more than 5 files at a time?","why":"Bulk upload requires an admin-granted, user-level-only permission.","atype":"Yes / No","options":["Yes","No"],"guidance":"","triggerText":"M1.05 = Yes","showIf":{"all":[{"ref":"M1.05","op":"eq","value":"Yes"}]},"routing":"If Yes -> record named users in Module 2","considerations":"'Upload up to 1,000 files at a time' is user-level only and cannot be granted to a group."},{"ref":"M1.07","tier":"modules","group":"M1","section":"M1 Ingestion","question":"Is ingestion via email attachment required?","why":"Email ingestion is US-only and unavailable on FedRAMP/GovRAMP accounts.","atype":"Yes / No","options":["Yes","No"],"guidance":"","triggerText":"M1.01 = Yes AND G1.07 = No","showIf":{"all":[{"ref":"M1.01","op":"eq","value":"Yes"},{"ref":"G1.07","op":"eq","value":"No"}]},"routing":"If Yes -> ask M1.08","considerations":"Email ingestion is U.S. only, max 5 attachments without bulk permission, ~25 MB provider cap."},{"ref":"M1.08","tier":"modules","group":"M1","section":"M1 Ingestion","question":"Which mailboxes or senders will forward agreements, and who owns that process?","why":"Email intake needs an owner or it silently degrades.","atype":"Free text","options":[],"guidance":"","triggerText":"M1.07 = Yes","showIf":{"all":[{"ref":"M1.07","op":"eq","value":"Yes"}]},"routing":"","considerations":""},{"ref":"M1.09","tier":"modules","group":"M1","section":"M1 Ingestion","question":"Is import from cloud storage required?","why":"Requires an administrator to install the relevant connector from App Center first.","atype":"Multi select","options":["Box","Dropbox","Google Drive","OneDrive","SharePoint","None"],"guidance":"","triggerText":"M1.01 = Yes","showIf":{"all":[{"ref":"M1.01","op":"eq","value":"Yes"}]},"routing":"If any selected -> admin must install from App Center before go-live","considerations":"Connector must be installed by an administrator before users can import."},{"ref":"M1.10","tier":"modules","group":"M1","section":"M1 Ingestion","question":"What file formats are present in the estate?","why":"Unsupported formats will need conversion before upload.","atype":"Multi select","options":["PDF","Word","Excel","PowerPoint","HTML","Images (JPG/PNG/TIF)","Other"],"guidance":"","triggerText":"M1.01 = Yes","showIf":{"all":[{"ref":"M1.01","op":"eq","value":"Yes"}]},"routing":"If 'Other' -> confirm conversion approach","considerations":"Supported: Word, Excel, HTML, images (JPG/PDF/PNG/TIF/TIFF), PowerPoint."},{"ref":"M1.11","tier":"modules","group":"M1","section":"M1 Ingestion","question":"Are any documents larger than 190 MB, or with filenames over 255 characters?","why":"Both are hard limits that cause silent upload failures.","atype":"Yes / No","options":["Yes","No","Unsure"],"guidance":"","triggerText":"M1.01 = Yes","showIf":{"all":[{"ref":"M1.01","op":"eq","value":"Yes"}]},"routing":"If Yes or Unsure -> run a file audit before migration","considerations":"190 MB file-size limit; 255-character filename limit."},{"ref":"M1.12","tier":"modules","group":"M1","section":"M1 Ingestion","question":"Is duplicate document detection required, and is it currently enabled?","why":"Behaviour differs by customer segment; eSignature-only accounts have it off by default.","atype":"Yes / No","options":["Yes","No","Unsure"],"guidance":"","triggerText":"M1.01 = Yes","showIf":{"all":[{"ref":"M1.01","op":"eq","value":"Yes"}]},"routing":"If eSignature-only account -> must be enabled on request","considerations":"English-only. Detects exact hash matches only. Skipped files auto-delete after 45 days."},{"ref":"M1.13","tier":"modules","group":"M1","section":"M1 Ingestion","question":"Who will monitor upload and processing jobs, and how often?","why":"Failed jobs are invisible unless someone checks the monitoring hub.","atype":"Free text","options":[],"guidance":"","triggerText":"M1.01 = Yes","showIf":{"all":[{"ref":"M1.01","op":"eq","value":"Yes"}]},"routing":"","considerations":""},{"ref":"M2.01","tier":"modules","group":"M2","section":"M2 Permissions","question":"Does this module apply? Confirm an access model needs to be designed or reviewed.","why":"Module gate.","atype":"Yes / No","options":["Yes","No"],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"If No -> skip to Module 3","considerations":""},{"ref":"M2.02","tier":"modules","group":"M2","section":"M2 Permissions","question":"Should any users have read-only visibility of all agreements?","why":"Maps to the 'View all agreements' permission.","atype":"Yes / No","options":["Yes","No"],"guidance":"","triggerText":"M2.01 = Yes","showIf":{"all":[{"ref":"M2.01","op":"eq","value":"Yes"}]},"routing":"If Yes -> capture named users or groups","considerations":"'View all agreements' cannot perform data review, or manage types, fields, sets or obligations."},{"ref":"M2.03","tier":"modules","group":"M2","section":"M2 Permissions","question":"Who needs full management rights across the repository?","why":"Maps to 'Organize and manage all agreements' - the highest access level.","atype":"Free text","options":[],"guidance":"","triggerText":"M2.01 = Yes","showIf":{"all":[{"ref":"M2.01","op":"eq","value":"Yes"}]},"routing":"","considerations":"Required for data review, obligations, custom types/fields, sets, hierarchies and party merging."},{"ref":"M2.04","tier":"modules","group":"M2","section":"M2 Permissions","question":"Will access be granted to individual users, to groups, or both?","why":"Bulk upload permission cannot be granted at group level.","atype":"Single select","options":["Users only","Groups only","Both"],"guidance":"","triggerText":"M2.01 = Yes","showIf":{"all":[{"ref":"M2.01","op":"eq","value":"Yes"}]},"routing":"If bulk upload needed -> must be granted per user","considerations":"The 'Everyone' group is a no-op for Agreement Manager access."},{"ref":"M2.05","tier":"modules","group":"M2","section":"M2 Permissions","question":"Should administrators be able to view agreement content, or only administer the system?","why":"Administrators do not get agreement visibility by default; this is a frequent misunderstanding.","atype":"Single select","options":["Administer only","Administer and view content"],"guidance":"","triggerText":"M2.01 = Yes","showIf":{"all":[{"ref":"M2.01","op":"eq","value":"Yes"}]},"routing":"","considerations":"Admins need explicit agreement-level permission; the admin role alone does not grant visibility."},{"ref":"M2.06","tier":"modules","group":"M2","section":"M2 Permissions","question":"Are there agreements that must be restricted to a named subset of users (e.g. HR, M&A, board)?","why":"Restricted content usually forces a set-based access design.","atype":"Yes / No","options":["Yes","No"],"guidance":"","triggerText":"M2.01 = Yes","showIf":{"all":[{"ref":"M2.01","op":"eq","value":"Yes"}]},"routing":"If Yes -> complete Module 5 (Sets) as mandatory, not optional","considerations":"There is no way to hide agreements from a user who has 'View all agreements'."},{"ref":"M2.07","tier":"modules","group":"M2","section":"M2 Permissions","question":"Do any users need to view agreements but be prevented from downloading them?","why":"This is not supported and often needs to be handled as a policy control.","atype":"Yes / No","options":["Yes","No"],"guidance":"","triggerText":"M2.01 = Yes","showIf":{"all":[{"ref":"M2.01","op":"eq","value":"Yes"}]},"routing":"If Yes -> flag as unsupported and agree a mitigation","considerations":"Download cannot be restricted for users with view access."},{"ref":"M2.08","tier":"modules","group":"M2","section":"M2 Permissions","question":"What is the joiner/mover/leaver process for agreement access?","why":"Access drift is the most common audit finding post-deployment.","atype":"Free text","options":[],"guidance":"","triggerText":"M2.01 = Yes","showIf":{"all":[{"ref":"M2.01","op":"eq","value":"Yes"}]},"routing":"","considerations":""},{"ref":"M2.09","tier":"modules","group":"M2","section":"M2 Audit","question":"Is an audit trail of who viewed or changed agreements required?","why":"Determines whether account-level activity logging needs to be part of the operating model.","atype":"Yes / No","options":["Yes","No"],"guidance":"","triggerText":"M2.01 = Yes","showIf":{"all":[{"ref":"M2.01","op":"eq","value":"Yes"}]},"routing":"If Yes -> ask M2.10 and M2.11","considerations":"Account-level activity log requires 'Organize and manage all agreements'."},{"ref":"M2.10","tier":"modules","group":"M2","section":"M2 Audit","question":"How long must audit evidence be retained, and does it need to be exported?","why":"Export caps mean long retention needs a scheduled extract process.","atype":"Free text","options":[],"guidance":"","triggerText":"M2.09 = Yes","showIf":{"all":[{"ref":"M2.09","op":"eq","value":"Yes"}]},"routing":"","considerations":"Activity log displays 200 events; CSV export capped at 5,000 rows; events can take 15 minutes to appear."},{"ref":"M2.11","tier":"modules","group":"M2","section":"M2 Audit","question":"Who will review permission changes, and how frequently?","why":"Admin audit logs are per account and need a named reviewer.","atype":"Free text","options":[],"guidance":"","triggerText":"M2.09 = Yes","showIf":{"all":[{"ref":"M2.09","op":"eq","value":"Yes"}]},"routing":"","considerations":"Audit logs export up to 1,000 records at a time; captured at account, not organisation, level."},{"ref":"M3.01","tier":"modules","group":"M3","section":"M3 Types & Fields","question":"Does this module apply? Confirm agreement types and fields need configuring.","why":"Module gate.","atype":"Yes / No","options":["Yes","No"],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"If No -> skip to Module 4","considerations":""},{"ref":"M3.02","tier":"modules","group":"M3","section":"M3 Types & Fields","question":"What agreement types exist in the estate, and which matter most?","why":"Standard types come pre-populated; anything else needs custom configuration.","atype":"Free text","options":[],"guidance":"","triggerText":"M3.01 = Yes","showIf":{"all":[{"ref":"M3.01","op":"eq","value":"Yes"}]},"routing":"Compare against the standard type list before designing custom types","considerations":"Unrecognised documents are classified as 'Miscellaneous'."},{"ref":"M3.03","tier":"modules","group":"M3","section":"M3 Types & Fields","question":"Are custom agreement types required beyond the Docusign standard set?","why":"Custom types are capped and, once created, deletion is irreversible.","atype":"Yes / No","options":["Yes","No","Unsure"],"guidance":"","triggerText":"M3.01 = Yes","showIf":{"all":[{"ref":"M3.01","op":"eq","value":"Yes"}]},"routing":"If Yes -> ask M3.04 and M3.05","considerations":"200 custom agreement types per account. Custom types can be deleted but not recovered."},{"ref":"M3.04","tier":"modules","group":"M3","section":"M3 Types & Fields","question":"How many custom types are anticipated, and who approves new ones?","why":"Governance prevents type sprawl, which degrades reporting quality.","atype":"Free text","options":[],"guidance":"","triggerText":"M3.03 = Yes","showIf":{"all":[{"ref":"M3.03","op":"eq","value":"Yes"}]},"routing":"","considerations":"AI detection for custom types counts against the extraction limit."},{"ref":"M3.05","tier":"modules","group":"M3","section":"M3 Types & Fields","question":"Should AI detection be enabled for custom types, or will they be assigned manually?","why":"AI detection consumes limited extraction capacity.","atype":"Single select","options":["AI detection","Manual assignment","Mix"],"guidance":"","triggerText":"M3.03 = Yes","showIf":{"all":[{"ref":"M3.03","op":"eq","value":"Yes"}]},"routing":"","considerations":"Pro/Enterprise/Sales: 50 combined with AI detection, 15 custom agreement types max. Without AI detection: 100 total."},{"ref":"M3.06","tier":"modules","group":"M3","section":"M3 Types & Fields","question":"What data points must be captured that are not in the standard extracted-insights set?","why":"Defines the custom field requirement.","atype":"Free text","options":[],"guidance":"","triggerText":"M3.01 = Yes","showIf":{"all":[{"ref":"M3.01","op":"eq","value":"Yes"}]},"routing":"Cross-check against the Extracted Insights dictionary first","considerations":"100 fields per agreement type. Custom fields cannot be deleted once created."},{"ref":"M3.07","tier":"modules","group":"M3","section":"M3 Types & Fields","question":"Which fields are mandatory for reporting, and which are nice-to-have?","why":"Prioritises the data review effort where it actually affects outcomes.","atype":"Free text","options":[],"guidance":"","triggerText":"M3.01 = Yes","showIf":{"all":[{"ref":"M3.01","op":"eq","value":"Yes"}]},"routing":"","considerations":""},{"ref":"M3.08","tier":"modules","group":"M3","section":"M3 Types & Fields","question":"Are any required values constrained to a fixed picklist (e.g. payment terms, renewal types)?","why":"Several standard dropdowns only extract pre-set values; anything else becomes 'Other'.","atype":"Yes / No","options":["Yes","No"],"guidance":"","triggerText":"M3.01 = Yes","showIf":{"all":[{"ref":"M3.01","op":"eq","value":"Yes"}]},"routing":"If Yes -> validate against the supported value sets","considerations":"Payment Term, Renewal Type, NDA Type, Party Role, Assignment, Employment Type and Late Fees Apply only extract pre-set values."},{"ref":"M3.09","tier":"modules","group":"M3","section":"M3 Types & Fields","question":"Are non-agreement documents (policies, certificates, forms, invoices) in scope?","why":"Several non-agreement types are not surfaced during processing.","atype":"Yes / No","options":["Yes","No"],"guidance":"","triggerText":"M3.01 = Yes","showIf":{"all":[{"ref":"M3.01","op":"eq","value":"Yes"}]},"routing":"","considerations":"Certificate, Handbook, Notice and Policy are NOT surfaced during processing."},{"ref":"M4.01","tier":"modules","group":"M4","section":"M4 Data Review","question":"Does this module apply? Confirm AI-surfaced data will be validated.","why":"Module gate. Data review is required for trustworthy reporting.","atype":"Yes / No","options":["Yes","No"],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"If No -> flag reporting accuracy risk in Considerations","considerations":""},{"ref":"M4.02","tier":"modules","group":"M4","section":"M4 Data Review","question":"Who is accountable for validating AI-suggested values, and at what volume per week?","why":"This is the largest recurring operational cost of the platform.","atype":"Free text","options":[],"guidance":"","triggerText":"M4.01 = Yes","showIf":{"all":[{"ref":"M4.01","op":"eq","value":"Yes"}]},"routing":"","considerations":"Requires 'Organize and manage all agreements'."},{"ref":"M4.03","tier":"modules","group":"M4","section":"M4 Data Review","question":"Will the whole back catalogue be reviewed, or only agreements above a materiality threshold?","why":"Full-catalogue review is rarely feasible; a threshold needs agreeing.","atype":"Single select","options":["All agreements","Above a value threshold","Active only","Specific types only"],"guidance":"","triggerText":"M4.01 = Yes","showIf":{"all":[{"ref":"M4.01","op":"eq","value":"Yes"}]},"routing":"","considerations":""},{"ref":"M4.04","tier":"modules","group":"M4","section":"M4 Data Review","question":"Is a target accuracy or completeness level defined for key fields?","why":"Gives a measurable definition of 'done' for the review effort.","atype":"Free text","options":[],"guidance":"","triggerText":"M4.01 = Yes","showIf":{"all":[{"ref":"M4.01","op":"eq","value":"Yes"}]},"routing":"","considerations":""},{"ref":"M4.05","tier":"modules","group":"M4","section":"M4 Data Review","question":"Should agreement details be captured at eSignature time to reduce downstream review?","why":"Fields set on the envelope flow straight through and avoid review entirely.","atype":"Yes / No","options":["Yes","No","Unsure"],"guidance":"","triggerText":"M4.01 = Yes","showIf":{"all":[{"ref":"M4.01","op":"eq","value":"Yes"}]},"routing":"If Yes -> engage the eSignature template owner","considerations":"Available on envelopes/templates: Automatic Renewal, Contract Value, Effective Date, Expiration Date, Renewal Notice Period, Renewal Term."},{"ref":"M4.06","tier":"modules","group":"M4","section":"M4 Data Review","question":"Is bulk correction of metadata expected as part of the deployment?","why":"Bulk metadata editing overwrites AI values permanently.","atype":"Yes / No","options":["Yes","No"],"guidance":"","triggerText":"M4.01 = Yes","showIf":{"all":[{"ref":"M4.01","op":"eq","value":"Yes"}]},"routing":"If Yes -> complete Module 12 (Migration & Bulk Data)","considerations":"Up to 10,000 agreements per job. Values become 'user-confirmed' and are excluded from future reprocessing."},{"ref":"M4.07","tier":"modules","group":"M4","section":"M4 Data Review","question":"How should the organisation handle reprocessing when new AI models are released?","why":"Reprocessing is opt-in and cannot be cancelled once started.","atype":"Single select","options":["Reprocess all","Reprocess selected","Do not reprocess","Undecided"],"guidance":"","triggerText":"M4.01 = Yes","showIf":{"all":[{"ref":"M4.01","op":"eq","value":"Yes"}]},"routing":"","considerations":"Reprocessing runs in the background and cannot be cancelled. User-entered values are never overwritten."},{"ref":"M5.01","tier":"modules","group":"M5","section":"M5 Sets","question":"Does this module apply? Confirm agreement sets are needed for organisation or access control.","why":"Module gate.","atype":"Yes / No","options":["Yes","No"],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"If M2.06 = Yes this module is mandatory","considerations":""},{"ref":"M5.02","tier":"modules","group":"M5","section":"M5 Sets","question":"Will sets be used primarily for organisation, for access control, or both?","why":"Access-control sets need far tighter governance than organisational ones.","atype":"Single select","options":["Organisation","Access control","Both"],"guidance":"","triggerText":"M5.01 = Yes","showIf":{"all":[{"ref":"M5.01","op":"eq","value":"Yes"}]},"routing":"","considerations":""},{"ref":"M5.03","tier":"modules","group":"M5","section":"M5 Sets","question":"How many sets are anticipated, and who owns their creation?","why":"There is a hard ceiling of 1,000 sets per account.","atype":"Free text","options":[],"guidance":"","triggerText":"M5.01 = Yes","showIf":{"all":[{"ref":"M5.01","op":"eq","value":"Yes"}]},"routing":"","considerations":"1,000 agreement sets per account. Creating sets requires 'Organize and manage all agreements'."},{"ref":"M5.04","tier":"modules","group":"M5","section":"M5 Sets","question":"Should sets populate automatically using smart filters, or be curated manually?","why":"Smart filters have specific logical limitations.","atype":"Single select","options":["Smart filters","Manual","Both"],"guidance":"","triggerText":"M5.01 = Yes","showIf":{"all":[{"ref":"M5.01","op":"eq","value":"Yes"}]},"routing":"If smart filters -> validate the filter logic is expressible","considerations":"Smart filters use AND across different fields, OR within the same field. Rolling date and duration-based filters are NOT supported."},{"ref":"M5.05","tier":"modules","group":"M5","section":"M5 Sets","question":"Do any required set rules depend on rolling dates (e.g. 'expiring in the next 90 days')?","why":"This is explicitly unsupported and needs an alternative design.","atype":"Yes / No","options":["Yes","No"],"guidance":"","triggerText":"M5.04 includes Smart filters","showIf":{"any":[{"ref":"M5.04","op":"containsAny","value":["Smart filters","Both"]}]},"routing":"If Yes -> redesign using dashboards or saved searches instead","considerations":"Smart filters do not support rolling date or duration-based conditions."},{"ref":"M5.06","tier":"modules","group":"M5","section":"M5 Sets","question":"Who should hold Set Manager, Set Collaborator and Set Viewer roles?","why":"Defines the set-level access model.","atype":"Free text","options":[],"guidance":"","triggerText":"M5.01 = Yes","showIf":{"all":[{"ref":"M5.01","op":"eq","value":"Yes"}]},"routing":"","considerations":""},{"ref":"M6.01","tier":"modules","group":"M6","section":"M6 Parties","question":"Does this module apply? Confirm party data quality is in scope.","why":"Module gate.","atype":"Yes / No","options":["Yes","No"],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"If No -> skip to Module 7","considerations":""},{"ref":"M6.02","tier":"modules","group":"M6","section":"M6 Parties","question":"Is there a known duplicate party problem (same counterparty under multiple names)?","why":"Duplicate parties break party-level reporting and the Party Hub.","atype":"Yes / No","options":["Yes","No","Unsure"],"guidance":"","triggerText":"M6.01 = Yes","showIf":{"all":[{"ref":"M6.01","op":"eq","value":"Yes"}]},"routing":"If Yes -> ask M6.03","considerations":"Standardisation handles case, whitespace, punctuation and legal descriptors. Inc. vs LLC remain distinct."},{"ref":"M6.03","tier":"modules","group":"M6","section":"M6 Parties","question":"Should the one-time party clean-up be run, and is the organisation aware it is irreversible?","why":"Clean-up cannot be paused, reverted or unmerged.","atype":"Yes / No","options":["Yes","No","Undecided"],"guidance":"","triggerText":"M6.02 = Yes","showIf":{"all":[{"ref":"M6.02","op":"eq","value":"Yes"}]},"routing":"If Yes -> obtain written sign-off before running","considerations":"IRREVERSIBLE. English-language documents only. Consolidated party takes the name of the oldest record."},{"ref":"M6.04","tier":"modules","group":"M6","section":"M6 Parties","question":"Is there a master vendor or customer list that party names should reconcile to?","why":"Determines whether party naming needs to align to an external system of record.","atype":"Yes / No","options":["Yes","No"],"guidance":"","triggerText":"M6.01 = Yes","showIf":{"all":[{"ref":"M6.01","op":"eq","value":"Yes"}]},"routing":"If Yes -> request the list and plan a reconciliation pass","considerations":""},{"ref":"M6.05","tier":"modules","group":"M6","section":"M6 Parties","question":"Do parties need to be classified as internal versus external?","why":"Party Side drives filtering and several dashboard views.","atype":"Yes / No","options":["Yes","No"],"guidance":"","triggerText":"M6.01 = Yes","showIf":{"all":[{"ref":"M6.01","op":"eq","value":"Yes"}]},"routing":"","considerations":""},{"ref":"M6.06","tier":"modules","group":"M6","section":"M6 Parties","question":"Are agreement hierarchies (master agreements with dependent SOWs, amendments) required?","why":"Hierarchies need Can Edit on the underlying agreements and are managed from the Party Hub.","atype":"Yes / No","options":["Yes","No"],"guidance":"","triggerText":"M6.01 = Yes","showIf":{"all":[{"ref":"M6.01","op":"eq","value":"Yes"}]},"routing":"If Yes -> confirm who holds Can Edit rights","considerations":"Creating hierarchies requires 'Organize and manage all agreements'."},{"ref":"M7.01","tier":"modules","group":"M7","section":"M7 Obligations","question":"Does this module apply? Confirm obligation tracking is in scope.","why":"Module gate. Obligation Management is a separate plan item.","atype":"Yes / No","options":["Yes","No"],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"If No -> skip to Module 8","considerations":"Requires the Obligation Management plan item."},{"ref":"M7.02","tier":"modules","group":"M7","section":"M7 Obligations","question":"Which obligation types must be tracked?","why":"Only a subset is AI-surfaced; the rest require manual creation.","atype":"Multi select","options":["Payment","Renewal notice","Termination notice","Compliance","Confidentiality","SLA","Warranty","Data breach","Other"],"guidance":"","triggerText":"M7.01 = Yes","showIf":{"all":[{"ref":"M7.01","op":"eq","value":"Yes"}]},"routing":"","considerations":"AI surfaces Payment, Renewal Notice and Termination only - and only for English (U.S.) agreements."},{"ref":"M7.03","tier":"modules","group":"M7","section":"M7 Obligations","question":"Are the in-scope agreements in English (U.S.)?","why":"Obligations AI runs on a U.S. server and does not support other languages.","atype":"Yes / No","options":["Yes","No","Mixed"],"guidance":"","triggerText":"M7.01 = Yes","showIf":{"all":[{"ref":"M7.01","op":"eq","value":"Yes"}]},"routing":"If No or Mixed -> obligations must be created manually for those agreements","considerations":"Obligations are AI-surfaced for English (U.S.) only. Dashboards will under-report for other languages."},{"ref":"M7.04","tier":"modules","group":"M7","section":"M7 Obligations","question":"Who is accountable for creating and closing manual obligations?","why":"Manual obligations decay without a named owner.","atype":"Free text","options":[],"guidance":"","triggerText":"M7.01 = Yes","showIf":{"all":[{"ref":"M7.01","op":"eq","value":"Yes"}]},"routing":"","considerations":""},{"ref":"M7.05","tier":"modules","group":"M7","section":"M7 Obligations","question":"What notification lead times are required before an obligation falls due?","why":"Drives subscription and notification configuration.","atype":"Free text","options":[],"guidance":"","triggerText":"M7.01 = Yes","showIf":{"all":[{"ref":"M7.01","op":"eq","value":"Yes"}]},"routing":"","considerations":""},{"ref":"M8.01","tier":"modules","group":"M8","section":"M8 Renewals","question":"Does this module apply? Confirm renewal management is in scope.","why":"Module gate.","atype":"Yes / No","options":["Yes","No"],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"If B2.03 = Yes this module is high priority","considerations":""},{"ref":"M8.02","tier":"modules","group":"M8","section":"M8 Renewals","question":"Which teams need renewal visibility, and at what lead time?","why":"Different functions need different horizons (procurement vs sales vs legal).","atype":"Free text","options":[],"guidance":"","triggerText":"M8.01 = Yes","showIf":{"all":[{"ref":"M8.01","op":"eq","value":"Yes"}]},"routing":"","considerations":""},{"ref":"M8.03","tier":"modules","group":"M8","section":"M8 Renewals","question":"Are Expiration Date, Renewal Type and Renewal Term reliably populated today?","why":"Auto-extension silently fails without all three.","atype":"Single select","options":["Yes","Partially","No","Unsure"],"guidance":"","triggerText":"M8.01 = Yes","showIf":{"all":[{"ref":"M8.01","op":"eq","value":"Yes"}]},"routing":"If not 'Yes' -> prioritise these fields in Module 4 data review","considerations":"Auto-extension requires accurate Expiration Date, Renewal Type and Renewal Term. No term value means the date is not extended."},{"ref":"M8.04","tier":"modules","group":"M8","section":"M8 Renewals","question":"Are there evergreen or auto-renewing agreements that need active monitoring?","why":"These are the highest-risk agreements in most estates.","atype":"Yes / No","options":["Yes","No","Unsure"],"guidance":"","triggerText":"M8.01 = Yes","showIf":{"all":[{"ref":"M8.01","op":"eq","value":"Yes"}]},"routing":"","considerations":""},{"ref":"M8.05","tier":"modules","group":"M8","section":"M8 Renewals","question":"Should renewal notifications be routed to individuals, or to a shared queue?","why":"Determines subscription design and resilience to staff turnover.","atype":"Single select","options":["Individuals","Shared queue","Both"],"guidance":"","triggerText":"M8.01 = Yes","showIf":{"all":[{"ref":"M8.01","op":"eq","value":"Yes"}]},"routing":"","considerations":"Notification preferences are all enabled by default and can be customised per type."},{"ref":"M9.01","tier":"modules","group":"M9","section":"M9 Reporting","question":"Does this module apply? Confirm dashboards and reporting are in scope.","why":"Module gate.","atype":"Yes / No","options":["Yes","No"],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"If No -> skip to Module 10","considerations":""},{"ref":"M9.02","tier":"modules","group":"M9","section":"M9 Reporting","question":"Which standard dashboards will be used, and by whom?","why":"Standard dashboards often cover more than expected, reducing custom build.","atype":"Multi select","options":["My dashboard","Administrator","Agreements","Obligations","Renewals","Requests"],"guidance":"","triggerText":"M9.01 = Yes","showIf":{"all":[{"ref":"M9.01","op":"eq","value":"Yes"}]},"routing":"","considerations":"The Obligations dashboard is English (U.S.) AI only."},{"ref":"M9.03","tier":"modules","group":"M9","section":"M9 Reporting","question":"Are custom dashboards or reports required?","why":"Custom builds are capped and need an owner.","atype":"Yes / No","options":["Yes","No"],"guidance":"","triggerText":"M9.01 = Yes","showIf":{"all":[{"ref":"M9.01","op":"eq","value":"Yes"}]},"routing":"If Yes -> ask M9.04","considerations":"Up to 100 custom dashboards, 10 widgets each."},{"ref":"M9.04","tier":"modules","group":"M9","section":"M9 Reporting","question":"What specific reports are required, and what fields do they depend on?","why":"Report requirements drive the field configuration in Module 3.","atype":"Free text","options":[],"guidance":"","triggerText":"M9.03 = Yes","showIf":{"all":[{"ref":"M9.03","op":"eq","value":"Yes"}]},"routing":"Cross-check every dependent field is supported for the relevant languages","considerations":"Top Liabilities, Late Fee Clauses, Assignment Controls and Payment Terms reports are English/French/German only."},{"ref":"M9.05","tier":"modules","group":"M9","section":"M9 Reporting","question":"Does any report need to cover more than 25,000 agreements in a single export?","why":"Hard export ceiling.","atype":"Yes / No","options":["Yes","No","Unsure"],"guidance":"","triggerText":"M9.01 = Yes","showIf":{"all":[{"ref":"M9.01","op":"eq","value":"Yes"}]},"routing":"If Yes -> design a segmented export approach","considerations":"CSV report export capped at 25,000 agreements."},{"ref":"M9.06","tier":"modules","group":"M9","section":"M9 Reporting","question":"Who needs scheduled report delivery, and at what frequency?","why":"Drives subscription configuration.","atype":"Free text","options":[],"guidance":"","triggerText":"M9.01 = Yes","showIf":{"all":[{"ref":"M9.01","op":"eq","value":"Yes"}]},"routing":"","considerations":"Sharing controls who can open a report; subscriptions control who receives it by email."},{"ref":"M9.07","tier":"modules","group":"M9","section":"M9 Reporting","question":"Does agreement data need to feed an external BI tool or data warehouse?","why":"Determines whether API or export-based integration is needed.","atype":"Yes / No","options":["Yes","No"],"guidance":"","triggerText":"M9.01 = Yes","showIf":{"all":[{"ref":"M9.01","op":"eq","value":"Yes"}]},"routing":"If Yes -> complete Module 11 (Integrations)","considerations":""},{"ref":"M10.01","tier":"modules","group":"M10","section":"M10 Automation","question":"Does this module apply? Confirm Conditional Rules automation is in scope.","why":"Module gate.","atype":"Yes / No","options":["Yes","No"],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"If No -> skip to Module 11","considerations":""},{"ref":"M10.02","tier":"modules","group":"M10","section":"M10 Automation","question":"What repetitive metadata corrections or standardisations happen today?","why":"These are the best candidates for the first rules.","atype":"Free text","options":[],"guidance":"","triggerText":"M10.01 = Yes","showIf":{"all":[{"ref":"M10.01","op":"eq","value":"Yes"}]},"routing":"","considerations":"Maximum 5 rules per account, each with up to 5 conditions."},{"ref":"M10.03","tier":"modules","group":"M10","section":"M10 Automation","question":"Should any downstream action be triggered automatically (e.g. raising a renewal request)?","why":"Rules can trigger Agreement Desk requests via Workflow Builder.","atype":"Yes / No","options":["Yes","No"],"guidance":"","triggerText":"M10.01 = Yes","showIf":{"all":[{"ref":"M10.01","op":"eq","value":"Yes"}]},"routing":"If Yes -> confirm Agreement Desk is licensed and configured","considerations":"Rules trigger Workflow Builder; complex routing belongs in Workflow Builder, not rules."},{"ref":"M10.04","tier":"modules","group":"M10","section":"M10 Automation","question":"Are the in-scope agreements in English?","why":"Conditional Rules are English-only at launch.","atype":"Yes / No","options":["Yes","No","Mixed"],"guidance":"","triggerText":"M10.01 = Yes","showIf":{"all":[{"ref":"M10.01","op":"eq","value":"Yes"}]},"routing":"If No -> rules are unavailable for those agreements","considerations":"Conditional Rules support English agreements only at launch."},{"ref":"M10.05","tier":"modules","group":"M10","section":"M10 Automation","question":"Who approves and governs rule changes?","why":"Rules silently rewrite data at scale and need change control.","atype":"Free text","options":[],"guidance":"","triggerText":"M10.01 = Yes","showIf":{"all":[{"ref":"M10.01","op":"eq","value":"Yes"}]},"routing":"","considerations":"A target field can only be updated by one rule. Each rule can reprocess up to 20,000 agreements."},{"ref":"M11.01","tier":"modules","group":"M11","section":"M11 Integrations","question":"Does this module apply? Confirm integration with other systems is in scope.","why":"Module gate.","atype":"Yes / No","options":["Yes","No"],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"If No -> skip to Module 12","considerations":""},{"ref":"M11.02","tier":"modules","group":"M11","section":"M11 Integrations","question":"Which systems must exchange data with Agreement Manager?","why":"Defines the integration surface.","atype":"Multi select","options":["Salesforce","SAP","Workday","NetSuite","ServiceNow","BI tool","Data warehouse","Other","None"],"guidance":"","triggerText":"M11.01 = Yes","showIf":{"all":[{"ref":"M11.01","op":"eq","value":"Yes"}]},"routing":"","considerations":""},{"ref":"M11.03","tier":"modules","group":"M11","section":"M11 Integrations","question":"If Docusign CLM is in use, what is the expected division of responsibility between CLM and Agreement Manager?","why":"Overlap between the two causes duplicated effort and conflicting data.","atype":"Free text","options":[],"guidance":"","triggerText":"G1.14 = In use today OR Planned","showIf":{"any":[{"ref":"G1.14","op":"eq","value":"In use today"},{"ref":"G1.14","op":"eq","value":"Planned"}]},"routing":"","considerations":"CLM attributes are read-only in Agreement Manager; edits must be made in CLM. Requires IAM Enterprise with CLM-IAM integration."},{"ref":"M11.04","tier":"modules","group":"M11","section":"M11 Integrations","question":"Is CLM-to-Agreement Manager document sync expected, and by when?","why":"Compatibility timelines have historically shifted.","atype":"Free text","options":[],"guidance":"","triggerText":"G1.14 = In use today OR Planned","showIf":{"any":[{"ref":"G1.14","op":"eq","value":"In use today"},{"ref":"G1.14","op":"eq","value":"Planned"}]},"routing":"","considerations":"CLM compatibility documented as expected early 2026 - validate current status with Docusign."},{"ref":"M11.05","tier":"modules","group":"M11","section":"M11 Integrations","question":"Is API access required, and does the team have development capacity?","why":"Determines whether integration is configuration or build.","atype":"Yes / No","options":["Yes","No","Unsure"],"guidance":"","triggerText":"M11.01 = Yes","showIf":{"all":[{"ref":"M11.01","op":"eq","value":"Yes"}]},"routing":"","considerations":""},{"ref":"M12.01","tier":"modules","group":"M12","section":"M12 Migration","question":"Does this module apply? Confirm documents or metadata will be migrated from another system.","why":"Module gate.","atype":"Yes / No","options":["Yes","No"],"guidance":"","triggerText":"G1.15 = Yes OR M4.06 = Yes","showIf":{"any":[{"ref":"G1.15","op":"eq","value":"Yes"},{"ref":"M4.06","op":"eq","value":"Yes"}]},"routing":"If No -> skip to Module 13","considerations":""},{"ref":"M12.02","tier":"modules","group":"M12","section":"M12 Migration","question":"Where are the documents held today, and in what volume?","why":"Sizes the migration and identifies extraction effort.","atype":"Free text","options":[],"guidance":"","triggerText":"M12.01 = Yes","showIf":{"all":[{"ref":"M12.01","op":"eq","value":"Yes"}]},"routing":"","considerations":""},{"ref":"M12.03","tier":"modules","group":"M12","section":"M12 Migration","question":"Does existing metadata need to be preserved, or will AI re-derive it?","why":"Determines whether bulk metadata editing is required.","atype":"Single select","options":["Preserve existing","Re-derive with AI","Both"],"guidance":"","triggerText":"M12.01 = Yes","showIf":{"all":[{"ref":"M12.01","op":"eq","value":"Yes"}]},"routing":"If 'Preserve' or 'Both' -> bulk metadata editing is in scope","considerations":"Custom fields must exist and be linked to the right agreement types BEFORE import, or values are silently skipped."},{"ref":"M12.04","tier":"modules","group":"M12","section":"M12 Migration","question":"Can the source system export a clean document-to-metadata mapping?","why":"Without a mapping, metadata migration is not feasible at scale.","atype":"Yes / No","options":["Yes","No","Unsure"],"guidance":"","triggerText":"M12.03 includes Preserve","showIf":{"any":[{"ref":"M12.03","op":"containsAny","value":["Preserve existing","Both"]}]},"routing":"If No -> re-scope to AI-derived metadata","considerations":""},{"ref":"M12.05","tier":"modules","group":"M12","section":"M12 Migration","question":"Is the migration a one-off cutover, or phased over time?","why":"Phasing affects duplicate detection and user communications.","atype":"Single select","options":["One-off","Phased","Undecided"],"guidance":"","triggerText":"M12.01 = Yes","showIf":{"all":[{"ref":"M12.01","op":"eq","value":"Yes"}]},"routing":"","considerations":"Bulk metadata editing handles up to 10,000 agreements per job; larger sets must be batched."},{"ref":"M12.06","tier":"modules","group":"M12","section":"M12 Migration","question":"Who validates that migrated data is complete and correct, and against what control totals?","why":"Migration without reconciliation is the commonest source of post-go-live disputes.","atype":"Free text","options":[],"guidance":"","triggerText":"M12.01 = Yes","showIf":{"all":[{"ref":"M12.01","op":"eq","value":"Yes"}]},"routing":"","considerations":""},{"ref":"M13.01","tier":"modules","group":"M13","section":"M13 Rollout","question":"Does this module apply? Confirm rollout and enablement planning is in scope.","why":"Module gate.","atype":"Yes / No","options":["Yes","No"],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"If No -> skip to Module 14","considerations":""},{"ref":"M13.02","tier":"modules","group":"M13","section":"M13 Rollout","question":"Will rollout be big-bang or phased by department, region or agreement type?","why":"Phasing reduces data review load and support burden.","atype":"Single select","options":["Big bang","Phased by department","Phased by region","Phased by type"],"guidance":"","triggerText":"M13.01 = Yes","showIf":{"all":[{"ref":"M13.01","op":"eq","value":"Yes"}]},"routing":"","considerations":""},{"ref":"M13.03","tier":"modules","group":"M13","section":"M13 Rollout","question":"What training is required for each audience?","why":"Administrators, contract managers and viewers need materially different training.","atype":"Free text","options":[],"guidance":"","triggerText":"M13.01 = Yes","showIf":{"all":[{"ref":"M13.01","op":"eq","value":"Yes"}]},"routing":"","considerations":""},{"ref":"M13.04","tier":"modules","group":"M13","section":"M13 Rollout","question":"Who provides first-line support after go-live?","why":"Determines the support model and escalation path.","atype":"Free text","options":[],"guidance":"","triggerText":"M13.01 = Yes","showIf":{"all":[{"ref":"M13.01","op":"eq","value":"Yes"}]},"routing":"","considerations":""},{"ref":"M13.05","tier":"modules","group":"M13","section":"M13 Rollout","question":"How will adoption be measured and encouraged?","why":"Repositories fail on adoption far more often than on configuration.","atype":"Free text","options":[],"guidance":"","triggerText":"M13.01 = Yes","showIf":{"all":[{"ref":"M13.01","op":"eq","value":"Yes"}]},"routing":"","considerations":""},{"ref":"M14.01","tier":"modules","group":"M14","section":"M14 Governance","question":"Does this module apply? Confirm ongoing governance needs defining.","why":"Module gate.","atype":"Yes / No","options":["Yes","No"],"guidance":"","triggerText":"Always ask","showIf":null,"routing":"","considerations":""},{"ref":"M14.02","tier":"modules","group":"M14","section":"M14 Governance","question":"Who owns the agreement type and field model on an ongoing basis?","why":"Without an owner, custom types and fields proliferate and hit the caps.","atype":"Free text","options":[],"guidance":"","triggerText":"M14.01 = Yes","showIf":{"all":[{"ref":"M14.01","op":"eq","value":"Yes"}]},"routing":"","considerations":"Custom fields cannot be deleted - only their AI detection can be removed to free capacity."},{"ref":"M14.03","tier":"modules","group":"M14","section":"M14 Governance","question":"How often will permissions and set membership be reviewed?","why":"Access review cadence is usually a compliance requirement.","atype":"Free text","options":[],"guidance":"","triggerText":"M14.01 = Yes","showIf":{"all":[{"ref":"M14.01","op":"eq","value":"Yes"}]},"routing":"","considerations":""},{"ref":"M14.04","tier":"modules","group":"M14","section":"M14 Governance","question":"Is the organisation opting in to Docusign AI data controls for model training?","why":"Requires both contractual consent and the in-product toggle.","atype":"Yes / No","options":["Yes","No","Unsure"],"guidance":"","triggerText":"M14.01 = Yes","showIf":{"all":[{"ref":"M14.01","op":"eq","value":"Yes"}]},"routing":"","considerations":"Training use requires BOTH contractual consent AND the AI Data Controls toggle enabled. Data is anonymised and aggregated."},{"ref":"M14.05","tier":"modules","group":"M14","section":"M14 Governance","question":"What is the process for evaluating and adopting new Agreement Manager features?","why":"The platform ships frequently; without a process, value is left on the table.","atype":"Free text","options":[],"guidance":"","triggerText":"M14.01 = Yes","showIf":{"all":[{"ref":"M14.01","op":"eq","value":"Yes"}]},"routing":"","considerations":"Pricing Preview features (Iris Chat, agents, Worksheets) run through end of 2026."},{"ref":"M14.06","tier":"modules","group":"M14","section":"M14 Governance","question":"When will the deployment be formally reviewed against the success measures in B2.11?","why":"Closes the loop on the business case.","atype":"Free text","options":[],"guidance":"","triggerText":"M14.01 = Yes","showIf":{"all":[{"ref":"M14.01","op":"eq","value":"Yes"}]},"routing":"","considerations":""}],"considerations":[{"ref":"C-01","trigger":"G1.07 = Yes (FedRAMP / GovRAMP)","cond":{"all":[{"ref":"G1.07","op":"eq","value":"Yes"}]},"constraint":"Email attachment ingestion is not supported on FedRAMP or GovRAMP accounts.","action":"Remove email intake from scope. Route those documents via bulk or cloud-storage upload."},{"ref":"C-02","trigger":"More than 100,000 agreements","cond":{"all":[{"ref":"G1.09","op":"gt","value":100000}]},"constraint":"Historical ingestion ceiling is 500,000 (North America) / 100,000 (International). Ingestion is all-or-nothing.","action":"Confirm the regional ceiling and raise an ingestion-filtering request with the account team if needed."},{"ref":"C-03","trigger":"More than 500,000 agreements","cond":{"all":[{"ref":"G1.09","op":"gt","value":500000}]},"constraint":"Volume exceeds the North American ceiling. Selective historical ingestion is not generally available.","action":"Escalate to Docusign before committing to a migration scope. Agree what will not be ingested."},{"ref":"C-04","trigger":"Docusign CLM in use or planned","cond":{"any":[{"ref":"G1.14","op":"eq","value":"In use today"},{"ref":"G1.14","op":"eq","value":"Planned"}]},"constraint":"CLM has its own deduplication and CLM interoperability documents are excluded from duplicate detection. CLM attributes are read-only in Agreement Manager and require IAM Enterprise with CLM-IAM integration.","action":"Confirm the edition supports CLM-IAM integration and validate current compatibility status with Docusign."},{"ref":"C-05","trigger":"External agreements to migrate","cond":{"all":[{"ref":"G1.15","op":"eq","value":"Yes"}]},"constraint":"Bulk upload requires the admin-granted 'Upload up to 1,000 files at a time' permission (user-level only). 190 MB file limit, 255-character filename limit.","action":"Complete the Migration module. Audit source files for size and filename violations before migration."},{"ref":"C-06","trigger":"Free-participant licences in scope","cond":{"all":[{"ref":"G1.17","op":"eq","value":"Yes"}]},"constraint":"Free participants can only see their own agreements. Dashboards render but load no data. Most features require a full licence plus permission.","action":"Reconcile the intended user list against licence entitlements before design sign-off."},{"ref":"C-07","trigger":"Multiple Docusign accounts","cond":{"all":[{"ref":"G1.04","op":"eq","value":"Multiple accounts"}]},"constraint":"Agreement Manager is issued at account level. There is no cross-account repository, and audit events are captured per account.","action":"Decide whether to consolidate accounts or run parallel deployments. Document the reporting impact."},{"ref":"C-08","trigger":"Not yet provisioned","cond":{"all":[{"ref":"G1.02","op":"eq","value":"No"}]},"constraint":"Historical ingestion begins automatically at provisioning and can take over a week for large estates.","action":"Sequence provisioning well ahead of go-live. Avoid month-end and year-end when queues are congested."},{"ref":"C-09","trigger":"Data residency requirements stated","cond":{"all":[{"ref":"G1.08","op":"answered"}]},"constraint":"Agreement data may be processed outside the provisioned region. The Obligations AI model runs on a U.S. server.","action":"Disclose to the client's privacy or legal function and obtain written acceptance before go-live."},{"ref":"C-10","trigger":"Non-English estate","cond":{"any":[{"ref":"G1.12","op":"containsAny","value":["English (other)","French","German","Spanish","Brazilian Portuguese","Japanese","Other"]}]},"constraint":"Payment Obligation insights are English (U.S.) only. Assignment, Liability, Jurisdiction, Execution Date, NDA Type and Title are English/German/French only. Custom types and fields are auto-supported in English (Global) only.","action":"Map every required field against the language support matrix. Plan manual entry for unsupported combinations."},{"ref":"C-11","trigger":"Languages answered without English (US)","cond":{"all":[{"ref":"G1.12","op":"answered"},{"ref":"G1.12","op":"notContains","value":"English (US)"}]},"constraint":"Obligations are not AI-surfaced outside English (U.S.), and the Obligations dashboard will under-report.","action":"Scope manual obligation creation, or descope Obligation Management."},{"ref":"C-12","trigger":"Edition not yet purchased","cond":{"all":[{"ref":"G1.01","op":"eq","value":"Not yet purchased"}]},"constraint":"Feature availability cannot be confirmed until the edition is known. Extraction limits and Obligation Management are edition-gated.","action":"Treat this as pre-sales discovery. Complete Business Discovery only and revisit the modules once the edition is agreed."},{"ref":"C-13","trigger":"Timeline stated","cond":{"all":[{"ref":"G1.18","op":"answered"}]},"constraint":"Processing large data sets can exceed a week. eSignature-ingested documents queue 4-5 days around month and year end.","action":"Validate the stated go-live against ingestion and review capacity. Build in contingency."},{"ref":"C-14","trigger":"Non-US datacenter region","cond":{"any":[{"ref":"G1.06","op":"eq","value":"EU"},{"ref":"G1.06","op":"eq","value":"Canada"},{"ref":"G1.06","op":"eq","value":"Australia"},{"ref":"G1.06","op":"eq","value":"Japan"}]},"constraint":"Non-US regions fall under 'English (Global)' rather than 'English (U.S.)', which excludes the Payment Obligation insight family.","action":"Confirm whether payment obligation tracking is required; if so, flag the gap explicitly."}],"groups":[{"id":"gate","tier":"gate","label":"Qualifying Gate","icon":"1"},{"id":"business","tier":"business","label":"Business Discovery","icon":"2"},{"id":"M1","tier":"modules","label":"M1. Ingestion & Intake","icon":"3"},{"id":"M2","tier":"modules","label":"M2. Permissions & Access","icon":"3"},{"id":"M3","tier":"modules","label":"M3. Types & Fields","icon":"3"},{"id":"M4","tier":"modules","label":"M4. Data Review","icon":"3"},{"id":"M5","tier":"modules","label":"M5. Agreement Sets","icon":"3"},{"id":"M6","tier":"modules","label":"M6. Party Management","icon":"3"},{"id":"M7","tier":"modules","label":"M7. Obligations","icon":"3"},{"id":"M8","tier":"modules","label":"M8. Renewals","icon":"3"},{"id":"M9","tier":"modules","label":"M9. Reporting","icon":"3"},{"id":"M10","tier":"modules","label":"M10. Automation","icon":"3"},{"id":"M11","tier":"modules","label":"M11. Integrations","icon":"3"},{"id":"M12","tier":"modules","label":"M12. Migration","icon":"3"},{"id":"M13","tier":"modules","label":"M13. Rollout","icon":"3"},{"id":"M14","tier":"modules","label":"M14. Governance","icon":"3"}]};